#include <cassert>
#include <cstdint>
#include <iostream>
#include <memory>
#include <numeric>
#include <random>
#include <vector>
#include "titan_cpplib/ds/dynamic_segment_tree.cpp"
#include "titan_cpplib/ds/dynamic_segment_tree_init.cpp"
using namespace std;
using ll = long long;
struct Counted {
    inline static uint64_t copies = 0, copy_assigns = 0, moves = 0, move_assigns = 0;
    inline static int live = 0;
    unique_ptr<ll> value;
    Counted() = delete;
    explicit Counted(ll x) : value(make_unique<ll>(x)) { ++live; }
    Counted(const Counted& other) : value(make_unique<ll>(other.get())) { ++copies; ++live; }
    Counted(Counted&& other) noexcept : value(move(other.value)) { ++moves; ++live; }
    Counted& operator=(const Counted& other) {
        value = make_unique<ll>(other.get());
        ++copy_assigns;
        return *this;
    }
    Counted& operator=(Counted&& other) noexcept {
        value = move(other.value);
        ++move_assigns;
        return *this;
    }
    ~Counted() { --live; }
    ll get() const { assert(value); return *value; }
};
Counted op(Counted a, Counted b) { return Counted(a.get()+b.get()); }
Counted e() { return Counted(0); }
Counted repeat(Counted a,ll n) { return Counted(a.get()*n); }
using Plain=titan23::DynamicSegmentTree<ll,Counted,op,e>;
using Initial=titan23::DynamicSegmentTreeInit<ll,Counted,op,e,repeat>;

template<class Tree>
void exercise(Tree& tree,ll initial,const char* label) {
    vector<ll> reference(257,initial);
    mt19937 rng(87531);
    Counted::copies=Counted::copy_assigns=Counted::moves=Counted::move_assigns=0;
    uint64_t checksum=0;
    for(int step=0;step<1000;++step) {
        const int k=rng()%257;
        const ll value=rng()%31;
        Counted supplied(value);
        if(step%2) tree.set(k,supplied);
        else tree.set(k,Counted(value));
        assert(supplied.get()==value);
        reference[k]=value;
        if(step%7==0) {
            int l=rng()%258,r=rng()%258;
            if(l>r) swap(l,r);
            const ll actual=tree.prod(l,r).get();
            const ll expected=accumulate(reference.begin()+l,reference.begin()+r,0LL);
            assert(actual==expected);
            checksum=(checksum*1000003)^uint64_t(actual);
        }
    }
    const ll total=accumulate(reference.begin(),reference.end(),0LL);
    assert(tree.all_prod().get()==total);
    checksum=(checksum*1000003)^uint64_t(total);
    cout<<label<<" checksum="<<checksum<<" copies="<<Counted::copies
        <<" copy_assigns="<<Counted::copy_assigns<<" moves="<<Counted::moves
        <<" move_assigns="<<Counted::move_assigns<<" nodes="<<tree.node_count()<<'\n';
}
int main() {
    {
        Plain tree(257);
        exercise(tree,0,"plain");
    }
    assert(Counted::live==0);
    {
        Initial tree(257,Counted(3));
        exercise(tree,3,"init");
    }
    assert(Counted::live==0);
}
